content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --success-color: #10b981;
  --success-hover: #059669;
  --secondary-color: #6b7280;
  --secondary-hover: #4b5563;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --radius: 12px;
  --shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
  padding: 20px;
}

.app-container {
  max-width: 800px;
  margin: 0 auto;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 24px;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 8px;
}

.stats-bar {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.badge {
  display: inline-block;
  padding: 6px 12px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 9999px;
  background-color: #e0e7ff;
  color: var(--primary-color);
}

.filter-bar {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.card-container {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

/* 3D Flip Card Styles */
.card {
  background-color: transparent;
  width: 100%;
  height: 220px;
  perspective: 1000px;
  cursor: pointer;
}

.card-inner {
  position: relative;
  width: 100%;
  height: 100%;
  text-align: center;
  transition: transform 0.6s;
  transform-style: preserve-3d;
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

.card.flipped .card-inner {
  transform: rotateY(180deg);
}

.card-front,
.card-back {
  position: absolute;
  width: 100%;
  height: 100%;
  -webkit-backface-visibility: hidden;
  backface-visibility: hidden;
  border-radius: var(--radius);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  padding: 20px;
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
}

.card-back {
  transform: rotateY(180deg);
  background-color: #f9fafb;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 16px;
  font-size: 0.875rem;
  font-weight: 600;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.btn-secondary {
  background-color: var(--secondary-color);
  color: white;
}

.btn-secondary:hover {
  background-color: var(--secondary-hover);
}

.btn-success {
  background-color: var(--success-color);
  color: white;
}

.btn-success:hover {
  background-color: var(--success-hover);
}

.form-container {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  border: 1px solid var(--border-color);
  margin-top: 24px;
}

.input-group {
  display: flex;
  gap: 12px;
  margin-bottom: 12px;
  flex-wrap: wrap;
}

.input {
  flex: 1;
  min-width: 140px;
  padding: 10px 14px;
  font-size: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.empty-msg {
  text-align: center;
  color: var(--text-muted);
  grid-column: 1 / -1;
  padding: 40px 0;
  font-size: 1rem;
}

@media (max-width: 480px) {
  body {
    padding: 10px;
  }
  .app-container {
    padding: 10px;
  }
  .input-group {
    flex-direction: column;
  }
  .input {
    width: 100%;
  }
}

export interface WordItem {
  id: string;
  english: string;
  japanese: string;
  category: string;
  status: 'learning' | 'mastered';
}

export interface CardItemProps {
  item: WordItem;
  onToggleStatus: (id: string, status: 'learning' | 'mastered') => void;
}

import { useState } from 'react';
import { CardItemProps } from './types';

export default function CardItem({ item, onToggleStatus }: CardItemProps) {
  const [isFlipped, setIsFlipped] = useState(false);

  const handleCardClick = () => {
    setIsFlipped(!isFlipped);
  };

  const handleStatusChange = (e: React.MouseEvent, status: 'learning' | 'mastered') => {
    e.stopPropagation();
    onToggleStatus(item.id, status);
  };

  return (
    <div className={`card ${isFlipped ? 'flipped' : ''}`} onClick={handleCardClick}>
      <div className="card-inner">
        <div className="card-front">
          <span className="badge" style={{ marginBottom: '12px' }}>{item.category}</span>
          <h3 style={{ fontSize: '1.5rem', marginBottom: '8px' }}>{item.english}</h3>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.875rem' }}>クリックして意味を確認</p>
        </div>
        <div className="card-back">
          <span className="badge" style={{ marginBottom: '12px' }}>{item.category}</span>
          <h3 style={{ fontSize: '1.5rem', marginBottom: '8px' }}>{item.japanese}</h3>
          <p style={{ fontSize: '0.9rem', marginBottom: '16px', color: 'var(--text-main)' }}>{item.english}</p>
          <div style={{ display: 'flex', gap: '8px' }} onClick={(e) => e.stopPropagation()}>
            <button
              className="btn btn-secondary"
              onClick={(e) => handleStatusChange(e, 'learning')}
            >
              もう一度
            </button>
            <button
              className="btn btn-success"
              onClick={(e) => handleStatusChange(e, 'mastered')}
            >
              知ってる
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { WordItem } from './types';
import CardItem from './CardItem';

const initialWords: WordItem[] = [
  { id: '1', english: 'Apple', japanese: 'りんご', category: '果物', status: 'learning' },
  { id: '2', english: 'Book', japanese: '本', category: '日常', status: 'learning' },
  { id: '3', english: 'Computer', japanese: 'コンピュータ', category: 'テクノロジー', status: 'learning' },
  { id: '4', english: 'Dog', japanese: '犬', category: '動物', status: 'mastered' },
  { id: '5', english: 'Elephant', japanese: 'ゾウ', category: '動物', status: 'learning' },
  { id: '6', english: 'Flower', japanese: '花', category: '自然', status: 'learning' },
  { id: '7', english: 'Guitar', japanese: 'ギター', category: '音楽', status: 'learning' },
  { id: '8', english: 'House', japanese: '家', category: '日常', status: 'mastered' },
  { id: '9', english: 'Island', japanese: '島', category: '自然', status: 'learning' },
  { id: '10', english: 'Journey', japanese: '旅', category: '日常', status: 'learning' },
];

export default function App() {
  const [words, setWords] = useState<WordItem[]>(initialWords);
  const [filter, setFilter] = useState<'all' | 'learning' | 'mastered'>('all');

  const [english, setEnglish] = useState('');
  const [japanese, setJapanese] = useState('');
  const [category, setCategory] = useState('日常');

  const handleToggleStatus = (id: string, status: 'learning' | 'mastered') => {
    setWords((prev) =>
      prev.map((word) => (word.id === id ? { ...word, status } : word))
    );
  };

  const handleAddWord = (e: React.FormEvent) => {
    e.preventDefault();
    if (!english.trim() || !japanese.trim()) return;

    const newItem: WordItem = {
      id: Date.now().toString(),
      english: english.trim(),
      japanese: japanese.trim(),
      category: category.trim() || '日常',
      status: 'learning',
    };

    setWords([newItem, ...words]);
    setEnglish('');
    setJapanese('');
  };

  const filteredWords = words.filter((word) => {
    if (filter === 'learning') return word.status === 'learning';
    if (filter === 'mastered') return word.status === 'mastered';
    return true;
  });

  const totalCount = words.length;
  const masteredCount = words.filter((w) => w.status === 'mastered').length;
  const learningCount = totalCount - masteredCount;

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">英単語 暗記カード</h1>
        <p style={{ color: 'var(--text-muted)' }}>カードをクリックして意味を確認しよう！</p>
      </header>

      <div className="stats-bar">
        <span className="badge">総単語数: {totalCount}</span>
        <span className="badge" style={{ backgroundColor: '#d1fae5', color: '#065f46' }}>
          知ってる: {masteredCount}
        </span>
        <span className="badge" style={{ backgroundColor: '#fef3c7', color: '#92400e' }}>
          学習中: {learningCount}
        </span>
      </div>

      <div className="filter-bar">
        <button
          className={`btn ${filter === 'all' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilter('all')}
        >
          すべて ({totalCount})
        </button>
        <button
          className={`btn ${filter === 'learning' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilter('learning')}
        >
          学習中 ({learningCount})
        </button>
        <button
          className={`btn ${filter === 'mastered' ? 'btn-primary' : 'btn-secondary'}`}
          onClick={() => setFilter('mastered')}
        >
          知ってる ({masteredCount})
        </button>
      </div>

      <div className="card-container">
        {filteredWords.length > 0 ? (
          filteredWords.map((item) => (
            <CardItem key={item.id} item={item} onToggleStatus={handleToggleStatus} />
          ))
        ) : (
          <div className="empty-msg">該当する単語がありません</div>
        )}
      </div>

      <div className="form-container">
        <h2 style={{ fontSize: '1.25rem', marginBottom: '16px', color: 'var(--primary-color)' }}>
          新しい単語を追加
        </h2>
        <form onSubmit={handleAddWord}>
          <div className="input-group">
            <input
              type="text"
              className="input"
              placeholder="英単語 (例: Apple)"
              value={english}
              onChange={(e) => setEnglish(e.target.value)}
            />
            <input
              type="text"
              className="input"
              placeholder="日本語訳 (例: りんご)"
              value={japanese}
              onChange={(e) => setJapanese(e.target.value)}
            />
            <input
              type="text"
              className="input"
              placeholder="カテゴリー (例: 果物)"
              value={category}
              onChange={(e) => setCategory(e.target.value)}
            />
            <button type="submit" className="btn btn-primary">
              追加
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
